import{_ as t,d as a,e as n,y as o}from"./chunks/framework.D7CAgLCq.js";const p=JSON.parse('{"title":"Formation, maintenance, recovery, and replication are different outcomes","description":"Evidence that an arrangement started does not settle whether it lasts, recovers, or can be replicated elsewhere.","frontmatter":{"title":"Formation, maintenance, recovery, and replication are different outcomes","description":"Evidence that an arrangement started does not settle whether it lasts, recovers, or can be replicated elsewhere."},"headers":[],"relativePath":"en/concepts/four-outcomes.md","filePath":"en/concepts/four-outcomes.md"}'),i={name:"en/concepts/four-outcomes.md"};function r(s,e,c,d,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="formation-maintenance-recovery-and-replication-are-different-outcomes" tabindex="-1">Formation, maintenance, recovery, and replication are different outcomes <a class="header-anchor" href="#formation-maintenance-recovery-and-replication-are-different-outcomes" aria-label="Permalink to &quot;Formation, maintenance, recovery, and replication are different outcomes&quot;">​</a></h1><p><strong>Evidence that an arrangement started does not settle whether it lasts, recovers, or can be replicated elsewhere.</strong></p><p>Formation concerns how an arrangement comes into being. Maintenance concerns what keeps it operating. Recovery concerns a specified function or identity after disruption. Replication concerns the result under a declared new realization or setting. Each needs its own target, conditions, window, and evidence.</p><p>A successful launch may rely on unusual founding resources. Routine operation may depend on maintenance labor that the launch record never measured. A recovery may meet a limited function while changing components. Replication may change the treatment itself when scale, implementation, or the object changes.</p><p>When replication fails, distinguish failure of the scheme itself, including the possibility that the original result was not caused by the scheme; deviation from the implementation specified beforehand; absence of a previously stated enabling condition; and a scale change that alters the treatment or object. Both implementation content and enabling conditions must be written before results and independently checkable. Inventing a missing condition after every failure shields the claim from correction.</p><p>An implementation deviation or missing enabling condition suggested only after failure remains a candidate for a later test. It does not revise the present result record. Whether an arrangement should be maintained, recovered, or replicated is also a separate normative judgment.</p><h2 id="keep-these-judgments-separate" tabindex="-1">Keep these judgments separate <a class="header-anchor" href="#keep-these-judgments-separate" aria-label="Permalink to &quot;Keep these judgments separate&quot;">​</a></h2><div class="xk-table"><table><thead><tr><th>A new result</th><th>A wider mechanism claim</th></tr></thead><tbody><tr><td>Evidence for the specific formation, maintenance, recovery, or replication task.</td><td>Requires the evidence and conditions of that additional task.</td></tr></tbody></table></div><h2 id="teaching-example-a-pilot-works-a-larger-program-does-not" tabindex="-1">Teaching example: a pilot works, a larger program does not <a class="header-anchor" href="#teaching-example-a-pilot-works-a-larger-program-does-not" aria-label="Permalink to &quot;Teaching example: a pilot works, a larger program does not&quot;">​</a></h2><p>Suppose a pilot uses a declared staffing ratio. A later rollout uses a different ratio and process. Record the actual implementation change; do not call it an identical treatment or invent an unrecorded condition after failure.</p><p><strong>Assumptions:</strong> Hypothetical comparison; the original conditions and actual difference are available.</p><p><strong>Boundary:</strong> The distinction alone does not identify which mechanism caused the failure.</p><h2 id="check-your-reading" tabindex="-1">Check your reading <a class="header-anchor" href="#check-your-reading" aria-label="Permalink to &quot;Check your reading&quot;">​</a></h2><p><strong>Can a failed replication be excused by any condition named afterward?</strong></p><p>No. A relevant enabling condition must have been stated beforehand and be independently checkable; other explanations remain candidates requiring evidence.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><p>Formation does not prove maintenance, and recovery does not prove unchanged identity.</p></li><li><p>Retain successes within their supported task even when another outcome fails.</p></li></ul><p>Read the complete <a href="/xi-kari-skill/handbook/en/theory/part-06.html#section-6-10-1">source section §6.10.1</a> and its guide. This explanation follows theory v2.1; the <a href="/xi-kari-skill/handbook/en/downloads.html">Chinese original</a> remains authoritative.</p>',18)])])}const u=t(i,[["render",r]]);export{p as __pageData,u as default};
